#include <stdio.h>

#define SLOTS 10

int shelf[SLOTS];
int used[SLOTS];

/* 编号算门牌号：编号除以 10 的余数 */
int slot_of(int id) {
    return id % SLOTS;
}

/* 存一只：从算出来的格子开始，有人住了就往后挪一格 */
void put(int id) {
    int slot = slot_of(id);
    while (used[slot]) {
        slot = (slot + 1) % SLOTS;
    }
    shelf[slot] = id;
    used[slot] = 1;
}

/* 找一只：从算出来的格子开始往后敲，答「比了几次」；一格都没住过就答 0 */
int find(int id) {
    int slot = slot_of(id);
    int tries = 0;
    while (used[slot]) {
        tries++;
        if (shelf[slot] == id) {
            return tries;
        }
        slot = (slot + 1) % SLOTS;
    }
    return 0;
}

int main(void) {
    put({a});
    put({b});

    int n1 = find({a});
    if (n1 > 0) {
        printf("找 %d：比了 %d 次\n", {a}, n1);
    } else {
        printf("找 %d：没找到\n", {a});
    }

    int n2 = find({b});
    if (n2 > 0) {
        printf("找 %d：比了 %d 次\n", {b}, n2);
    } else {
        printf("找 %d：没找到\n", {b});
